{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TEMP TABLE Zepto_Inventory_Base AS SELECT CAST(Date AS DATE) AS DATA_FETCH_DATE, CAST(EAN AS STRING) AS EAN, LOWER(TRIM(SKU_Code)) AS SKU, City AS CITY, SKU_Name AS SKU_NAME_RAW, SKU_Category AS SKU_CATEGORY_RAW, SKU_Sub_Category AS SKU_SUB_CATEGORY_RAW, Brand_Name AS BRAND_RAW, SUM(IFNULL(SAFE_CAST(Units AS INT64), 0)) AS AVAILABLE_INVENTORY FROM `maplemonk.zouk_Zepto_inventory` GROUP BY 1, 2, 3, 4, 5, 6, 7, 8; CREATE TEMP TABLE Zepto_Sales_Daily AS SELECT CAST(Date AS DATE) AS ORDER_DATE, LOWER(TRIM(SKU_Number)) AS SKU, City AS CITY, SUM(IFNULL(SAFE_CAST(Sales__Qty____Units AS INT64), 0)) AS QUANTITY, SUM(IFNULL(SAFE_CAST(Gross_Merchandise_Value AS FLOAT64), 0)) AS GMV, SAFE_DIVIDE( SUM(IFNULL(SAFE_CAST(Gross_Merchandise_Value AS FLOAT64), 0)), NULLIF(SUM(IFNULL(SAFE_CAST(Sales__Qty____Units AS INT64), 0)), 0) ) AS AVG_SELLING_PRICE FROM `MapleMonk.Zouk_new_db_Zepto_sales` GROUP BY 1, 2, 3; CREATE TEMP TABLE Zepto_Pre_DRR AS SELECT SD.ORDER_DATE AS DATE, SD.SKU, SD.CITY, SD.QUANTITY, CASE WHEN IFNULL(SD.QUANTITY, 0) > 0 THEN 1 ELSE 0 END AS DRR_FLAG FROM Zepto_Sales_Daily SD WHERE SD.ORDER_DATE >= DATE_SUB( (SELECT MAX(CAST(Date AS DATE)) FROM `maplemonk.zouk_Zepto_inventory`), INTERVAL 91 DAY ); CREATE TEMP TABLE Zepto_Final_DRR AS SELECT PD.DATE, PD.SKU, PD.CITY, SUM( CASE WHEN PDR.DRR_FLAG = 1 THEN IFNULL(PDR.QUANTITY, 0) ELSE 0 END ) AS DRR_QUANTITY, SUM(IFNULL(PDR.DRR_FLAG, 0)) AS DRR_DAYS FROM Zepto_Pre_DRR PD LEFT JOIN Zepto_Pre_DRR PDR ON PD.SKU = PDR.SKU AND PD.CITY = PDR.CITY AND DATE_DIFF(PD.DATE, PDR.DATE, DAY) <= 90 AND DATE_DIFF(PD.DATE, PDR.DATE, DAY) > 0 GROUP BY 1, 2, 3; CREATE TEMP TABLE Product_Master_Deduped AS SELECT * FROM ( SELECT CAST(EAN AS STRING) AS EAN, COMMONSKU AS SKU_CODE, NAME AS PRODUCT_NAME, BRAND AS BRAND, CATEGORY AS CATEGORY, CATEGORY_CODE AS CATEGORY_CODE, collection AS COLLECTION, PRODUCT_TYPE AS PRODUCT_TYPE, PRODUCT_BUCKET AS PRODUCT_BUCKET, Type AS SKU_TYPE, CAST(colour AS STRING) AS COLOR, CAST(SIZE AS STRING) AS SIZE, IFNULL(SAFE_CAST(MRP AS FLOAT64), 0.0) AS MRP, IFNULL(SAFE_CAST(BAU_Online AS FLOAT64), 0.0) AS BAU_ONLINE, ROW_NUMBER() OVER ( PARTITION BY CAST(EAN AS STRING) ORDER BY 1 ) AS rw FROM `maplemonk.FINAL_SKU_MASTER` WHERE EAN IS NOT NULL ) WHERE rw = 1; CREATE TEMP TABLE Zepto_Sales_Windowed AS WITH base AS ( SELECT INV.DATA_FETCH_DATE, INV.EAN, INV.SKU, INV.CITY, INV.AVAILABLE_INVENTORY, INV.SKU_CATEGORY_RAW AS ZEPTO_CATEGORY, INV.SKU_SUB_CATEGORY_RAW AS ZEPTO_SUB_CATEGORY, COALESCE(PM.CATEGORY, \'\') AS CATEGORY, COALESCE(PM.CATEGORY_CODE, \'\') AS CATEGORY_CODE, COALESCE(PM.SKU_CODE, INV.SKU) AS COMMONSKU, COALESCE(PM.PRODUCT_NAME, INV.SKU_NAME_RAW) AS PRODUCT_NAME, COALESCE(PM.COLLECTION, \'\') AS COLLECTION, COALESCE(PM.PRODUCT_TYPE, \'\') AS PRODUCT_TYPE, COALESCE(PM.PRODUCT_BUCKET, \'\') AS PRODUCT_BUCKET, COALESCE(PM.SKU_TYPE, \'\') AS SKU_TYPE, COALESCE(PM.COLOR, \'\') AS COLOR, COALESCE(PM.SIZE, \'\') AS SIZE, COALESCE(PM.MRP, 0.0) AS MRP, COALESCE(PM.BAU_ONLINE, 0.0) AS BAU_ONLINE, CASE WHEN LOWER(TRIM(PM.BRAND)) LIKE \'%zouk%\' THEN \'ZOUK\' WHEN LOWER(TRIM(PM.BRAND)) LIKE \'%everpret%\' THEN \'EVERPRET\' WHEN LOWER(TRIM(PM.BRAND)) LIKE \'%doto%\' THEN \'DOTO\' WHEN LOWER(TRIM(PM.BRAND)) LIKE \'%1991%\' THEN \'1991\' ELSE UPPER(TRIM(COALESCE(PM.BRAND, INV.BRAND_RAW))) END AS BRAND, CASE WHEN PM.EAN IS NOT NULL THEN \'ean_match\' ELSE \'no_match\' END AS PM_MATCH_TYPE, SD.ORDER_DATE, SD.QUANTITY, SD.GMV FROM Zepto_Inventory_Base INV LEFT JOIN Product_Master_Deduped PM ON INV.EAN = PM.EAN LEFT JOIN Zepto_Sales_Daily SD ON INV.SKU = SD.SKU AND INV.CITY = SD.CITY ) SELECT DATA_FETCH_DATE, EAN, SKU, CITY, AVAILABLE_INVENTORY, ANY_VALUE(COMMONSKU) AS COMMONSKU, ANY_VALUE(PRODUCT_NAME) AS PRODUCT_NAME, ANY_VALUE(ZEPTO_CATEGORY) AS ZEPTO_CATEGORY, ANY_VALUE(ZEPTO_SUB_CATEGORY) AS ZEPTO_SUB_CATEGORY, ANY_VALUE(CATEGORY) AS CATEGORY, ANY_VALUE(CATEGORY_CODE) AS CATEGORY_CODE, ANY_VALUE(COLLECTION) AS COLLECTION, ANY_VALUE(PRODUCT_TYPE) AS PRODUCT_TYPE, ANY_VALUE(PRODUCT_BUCKET) AS PRODUCT_BUCKET, ANY_VALUE(SKU_TYPE) AS SKU_TYPE, ANY_VALUE(COLOR) AS COLOR, ANY_VALUE(SIZE) AS SIZE, ANY_VALUE(MRP) AS MRP, ANY_VALUE(BAU_ONLINE) AS BAU_ONLINE, ANY_VALUE(BRAND) AS BRAND, ANY_VALUE(PM_MATCH_TYPE) AS PM_MATCH_TYPE, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) = 1 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_LAST_DAY, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) = 1 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_LAST_DAY, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 7 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_7D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 7 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_7D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 14 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_14D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 14 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_14D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 30 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_30D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 30 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_30D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 56 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_56D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 56 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_56D, SUM(CASE WHEN DATE_TRUNC(ORDER_DATE, MONTH) = DATE_TRUNC(DATA_FETCH_DATE, MONTH) AND ORDER_DATE < DATA_FETCH_DATE THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_MTD, SUM(CASE WHEN DATE_TRUNC(ORDER_DATE, MONTH) = DATE_TRUNC(DATA_FETCH_DATE, MONTH) AND ORDER_DATE < DATA_FETCH_DATE THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_MTD FROM base GROUP BY 1, 2, 3, 4, 5; CREATE OR REPLACE TABLE `maplemonk.zepto_inventory_fact_Items` AS WITH DOH_BASE AS ( SELECT SW.*, IFNULL(FD.DRR_QUANTITY, 0) AS DRR_QUANTITY_90D, IFNULL(FD.DRR_DAYS, 0) AS DRR_DAYS_90D, CASE WHEN IFNULL(FD.DRR_DAYS, 0) > 0 THEN ROUND(SAFE_DIVIDE(FD.DRR_QUANTITY, FD.DRR_DAYS), 2) ELSE 0 END AS DRR, CASE WHEN SW.AVAILABLE_INVENTORY > 1 THEN 1 ELSE 0 END AS AVAILABILITY FROM Zepto_Sales_Windowed SW LEFT JOIN Zepto_Final_DRR FD ON CAST(SW.DATA_FETCH_DATE AS DATE) = CAST(FD.DATE AS DATE) AND SW.SKU = FD.SKU AND SW.CITY = FD.CITY ) SELECT DATA_FETCH_DATE, EAN, SKU, COMMONSKU, PM_MATCH_TYPE, CITY, PRODUCT_NAME, BRAND, ZEPTO_CATEGORY, ZEPTO_SUB_CATEGORY, CATEGORY, CATEGORY_CODE, COLLECTION, PRODUCT_TYPE, PRODUCT_BUCKET, SKU_TYPE, COLOR, SIZE, MRP, BAU_ONLINE, AVAILABLE_INVENTORY, AVAILABILITY, SOLD_QTY_LAST_DAY, GMV_LAST_DAY, SOLD_QTY_7D, GMV_7D, SOLD_QTY_14D, GMV_14D, SOLD_QTY_30D, GMV_30D, SOLD_QTY_56D, GMV_56D, SOLD_QTY_MTD, GMV_MTD, DRR_QUANTITY_90D, DRR_DAYS_90D, DRR, CASE WHEN DRR = 0 THEN NULL ELSE LEAST(ROUND(SAFE_DIVIDE(AVAILABLE_INVENTORY, DRR), 1), 999) END AS DOH, CASE WHEN DRR = 0 THEN \'No Sales\' WHEN SAFE_DIVIDE(AVAILABLE_INVENTORY, DRR) < 7 THEN \'Critical\' WHEN SAFE_DIVIDE(AVAILABLE_INVENTORY, DRR) BETWEEN 7 AND 14 THEN \'Low\' WHEN SAFE_DIVIDE(AVAILABLE_INVENTORY, DRR) BETWEEN 14 AND 60 THEN \'Healthy\' ELSE \'Overstocked\' END AS STOCK_STATUS, ROUND( IFNULL( SAFE_DIVIDE(GMV_LAST_DAY, NULLIF(SOLD_QTY_LAST_DAY, 0)), BAU_ONLINE ) * AVAILABLE_INVENTORY, 2) AS INVENTORY_VALUE FROM DOH_BASE;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            